mapper.select:
SELECT instrument_id, ticker, name, type, currency, tradable, exchange, sector
FROM Instruments
WHERE ticker = #{symbol}

SELECT instrument_id, ticker, name, type, currency, tradable, exchange, sector
FROM Instruments
WHERE instrument_id = #{instrumentId}

mapper.sql:
WHERE tradable = true

    AND (lower(ticker) LIKE #{query} ESCAPE '!' OR lower(name) LIKE #{query} ESCAPE '!')

AND exchange = #{exchange}
AND sector = #{sector}
AND type::text = #{type}
